package com.greatleyposhley.professy.collaboration;
import com.greatleyposhley.professy.entities.*;import com.greatleyposhley.professy.repositories.UserAccountRepository;import com.greatleyposhley.professy.services.UserAccountService;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class UserOrganizationAssignmentTest {
 @Test void clearingOneAssignmentPreservesTheOtherUnits(){var users=mock(UserAccountRepository.class);var jdbc=mock(JdbcTemplate.class);var policy=mock(WorkspacePolicy.class);var access=spy(new WorkAccess(users,jdbc,policy));var actor=new UserAccount();actor.setId(1L);actor.setOrgId(7L);doReturn(actor).when(access).actor();when(policy.can(actor,"USERS.UPDATE")).thenReturn(true);var structure=mock(OrganizationStructure.class);when(structure.names(anyList())).thenAnswer(call->call.getArgument(0));var existing=new UserAccount();existing.setId(2L);existing.setOrgId(7L);existing.setDepartmentId(10L);existing.setFunctionId(11L);existing.setDivisionId(12L);when(users.findById(2L)).thenReturn(Optional.of(existing));when(users.save(any())).thenAnswer(call->call.getArgument(0));var service=new UserAccountService(users,mock(PasswordEncoder.class),mock(PasswordSetupService.class),access,structure);var updates=new UserAccount();updates.setDepartmentId(null);service.updateUser(7L,2L,updates);assertNull(existing.getDepartmentId());assertEquals(11L,existing.getFunctionId());assertEquals(12L,existing.getDivisionId());verify(access).require("USERS.UPDATE");verify(structure).validateChanges(updates,existing);}
 @Test void unitAssignmentCannotReferenceAnotherOrganization(){var jdbc=mock(JdbcTemplate.class);when(jdbc.queryForObject(startsWith("SELECT COUNT(*) FROM organization_units"),eq(Integer.class),eq(10L),eq(7L),eq("DEPARTMENT"))).thenReturn(0);var person=new UserAccount();person.setOrgId(7L);person.setDepartmentId(10L);assertThrows(IllegalArgumentException.class,()->new OrganizationStructure(jdbc).validate(person));}
}
